import{_ as e}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a,a as l,b as r,c as n,d as s,e as p,f as c,g as d,h as u,i as m,j as g,k as h}from"./chunks/M-S-SW-BJe4.xYg88VDv.js";import{_ as o}from"./chunks/ON.DXVlsWbj.js";import{_ as t}from"./chunks/OFF.BrU7kQE-.js";import{_ as b}from"./chunks/EN.P9aPnFBv.js";import{_ as f,o as v,c as y,a3 as x}from"./chunks/framework.g9mfNVRQ.js";const j=JSON.parse('{"title":"Orologio BlueJay","description":"","frontmatter":{"source_hash":"498f98f131","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/smartwatch/bluejay.md","filePath":"it/smartwatch/bluejay.md"}'),z={name:"it/smartwatch/bluejay.md"};function _(S,i,q,D,w,B){return v(),y("div",null,[...i[0]||(i[0]=[x('<div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_watch_grey600_48dp.png" style="width:5%;"> Caratteristiche Collegamenti Smart Watch<br>   BlueJay Watch</p></div><p>Puoi acquistare il tuo orologio BlueJay <a href="https://bluejay.website/" target="_blank" rel="noreferrer">qui: <img src="'+a+'" style="zoom:100%;"></a></p><p>Il <a href="https://bluejay.website/shop" target="_blank" rel="noreferrer">BlueJay U3</a> è il modello attuale ed è già disponibile. Esegue il pacchetto xDrip completo su Android e si collega direttamente ai sensori G6, G7 e Dexcom ONE/ONE+.</p><p>I modelli precedenti X2, GTS, U1 e U2 <strong>non sono più in vendita</strong>. Le loro istruzioni di configurazione restano qui sotto per chi li possiede già.<br> Riferimenti dei modelli precedenti: <a href="https://bluejay.website/shop/product/bluejay-gts-26" target="_blank" rel="noreferrer">GTS</a> (autonomo o con xDrip), <a href="https://bluejay.website/shop/product/bluejay-u1-27" target="_blank" rel="noreferrer">U1</a> e <a href="https://bluejay.website/shop/product/bluejay-u2-28" target="_blank" rel="noreferrer">U2</a>.</p><div class="info custom-block"><p class="custom-block-title">Condivisione della glicemia</p><p>I BlueJay X2/GTS sono solo Bluetooth e non possono condividere i dati della glicemia se non sono collegati a xDrip sul telefono.<br> Gli U1/U2/U3 eseguono xDrip completo e possono anche ritrasmettere le letture a un telefono o ad altri follower tramite Bluetooth (xDrip Link) o internet (xDrip Sync).</p></div><p>Gli orologi BlueJay sono compagni potenti per i sensori G6, G7 e 1/1+. Si collegano direttamente al trasmettitore, ma devi conoscerne i limiti.</p><h5 id="g6g7-and-11" tabindex="-1">G6/G7 e 1/1+ <a class="header-anchor" href="#g6g7-and-11" aria-label="Permalink to &quot;G6/G7 e 1/1+ {#g6g7-and-11}&quot;">​</a></h5><p>Questi trasmettitori hanno due slot Bluetooth: phone (telefono) e non-phone (non telefono).<br> Puoi configurare gli slot secondo la tabella qui sotto. Al trasmettitore possono essere collegati contemporaneamente solo due dispositivi, ciascuno su uno slot diverso.<br> Per impostazione predefinita BlueJay usa lo slot non-phone. Vedi <a href="#run-collector">qui per il GTS</a> come modificare questa impostazione.</p><p>U1, U2 e U3 devono essere collegati per primi al sensore. Una volta collegati, puoi attivare anche la seconda connessione e l&#39;orologio sceglierà automaticamente lo slot libero.</p><table tabindex="0"><thead><tr><th>App del produttore</th><th>Ricevitore</th><th>Microinfusore collegato</th><th>Orologio BlueJay</th></tr></thead><tbody><tr><td>Non utilizzabile</td><td>Non utilizzabile</td><td>Non utilizzabile</td><td>Slot non-phone <strong>xDrip usa lo slot phone</strong></td></tr><tr><td><strong>Usa lo slot phone</strong></td><td>Non utilizzabile</td><td>Non utilizzabile</td><td>Slot non-phone</td></tr><tr><td>Non utilizzabile</td><td><strong>Usa lo slot non-phone</strong></td><td>Non utilizzabile</td><td>Slot phone</td></tr><tr><td>Non utilizzabile</td><td>Non utilizzabile</td><td>t:slim, Omnipod 5 <strong>usano gli slot non-phone</strong></td><td>Slot phone</td></tr><tr><td>Non utilizzabile</td><td>Non utilizzabile</td><td>CamAPS, DBLG1 <strong>usano lo slot phone</strong></td><td>Slot non-phone</td></tr></tbody></table><p><em>Nota: per impostazione predefinita xDrip usa lo slot phone; lo slot non-phone richiede l&#39;Engineering mode</em></p><h2 id="bluejay-u3" tabindex="-1">BlueJay U3 <a class="header-anchor" href="#bluejay-u3" aria-label="Permalink to &quot;BlueJay U3 {#bluejay-u3}&quot;">​</a></h2><p>L&#39;U3 esegue Android completo e il core di xDrip direttamente sull&#39;orologio. Lo configuri sull&#39;orologio e, se vuoi, puoi ritrasmettere le letture al telefono.</p><h3 id="u3-controls" tabindex="-1">Comandi dell&#39;U3 <a class="header-anchor" href="#u3-controls" aria-label="Permalink to &quot;Comandi dell&#39;U3 {#u3-controls}&quot;">​</a></h3><p>L&#39;U3 ha due pulsanti fisici: un pulsante <strong>sinistro</strong> (arancione) e un pulsante <strong>destro</strong>. Sugli U1/U2 il comando a destra era una corona; sull&#39;U3 in quella posizione c&#39;è la fotocamera.</p><ul><li>Premi uno qualsiasi dei due pulsanti per riattivare lo schermo.</li><li>Il pulsante <strong>destro</strong> spegne lo schermo.</li><li>Il pulsante <strong>sinistro</strong> torna indietro.</li><li>Tieni premuto il pulsante di accensione per il menu Shutdown / Reboot / SOS, poi scorri verso destra l&#39;opzione che vuoi.</li></ul><h3 id="get-readings-on-the-u3" tabindex="-1">Ricevere le letture sull&#39;U3 <a class="header-anchor" href="#get-readings-on-the-u3" aria-label="Permalink to &quot;Ricevere le letture sull&#39;U3 {#get-readings-on-the-u3}&quot;">​</a></h3><p>Imposta l&#39;identificativo del sensore in xDrip sull&#39;orologio, esattamente come faresti su un telefono: vai in Impostazioni  ›  Dati Hardware di origine  ›  DexcomG5/G6/G7.</p><ul><li><strong>G6</strong>: inserisci l&#39;<strong>ID del trasmettitore (TXID)</strong>.</li><li><strong>G7 / Dexcom ONE+</strong>: inserisci il <strong>codice di accoppiamento a 4 cifre</strong>.</li></ul><p>Con un sensore nuovo, imposta prima l&#39;ID o il codice sull&#39;orologio e lascia che riceva le letture prima di impostarlo in qualsiasi app del telefono. Con un sensore già in funzione e collegato a un&#39;app del telefono, disattiva temporaneamente l&#39;app del telefono (spegnila, disattiva il Bluetooth o allontanati), collega l&#39;orologio, poi riattiva l&#39;app del telefono quando l&#39;orologio riceve le letture.</p><h3 id="transmitter-slot" tabindex="-1">Slot del trasmettitore <a class="header-anchor" href="#transmitter-slot" aria-label="Permalink to &quot;Slot del trasmettitore {#transmitter-slot}&quot;">​</a></h3><p>Per impostazione predefinita l&#39;U3 usa lo <strong>slot non-phone</strong>. Consulta la <a href="#g6g7-and-11">tabella degli slot qui sopra</a> per scegliere lo slot giusto. Per spostare l&#39;orologio sullo <strong>slot phone</strong>, scansiona il codice QR corrispondente in:</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Configurazione automatica</p></div><p>Evita di cambiare ripetutamente il dispositivo su uno slot: il sensore potrebbe bloccarsi. Lo slot è una configurazione fissa, non uno scambio a caldo.</p><div class="warning custom-block"><p class="custom-block-title">Aggiornamento canale phone per il G7</p><p>Se l&#39;orologio smette di ricevere le letture del <strong>G7</strong>, applica l&#39;aggiornamento software dell&#39;orologio: sull&#39;orologio apri <strong>Impostazioni Android › Software Upgrade</strong>, con il Wi-Fi connesso e in carica (batteria &gt; 25%), cerca gli aggiornamenti e installali.<br> Dopo puoi passare l&#39;orologio sul canale phone scansionando il codice QR mostrato in xDrip <strong>Impostazioni › Configurazione automatica</strong>, poi riavvia l&#39;orologio.<br> Con questo metodo <strong>l&#39;orologio e un&#39;app del telefono non possono entrambi</strong> ricevere le letture direttamente dal sensore: disattiva il collector dell&#39;app del telefono se il collector è l&#39;orologio.</p></div><h3 id="snooze-an-xdrip-alarm" tabindex="-1">Posticipare un allarme di xDrip <a class="header-anchor" href="#snooze-an-xdrip-alarm" aria-label="Permalink to &quot;Posticipare un allarme di xDrip {#snooze-an-xdrip-alarm}&quot;">​</a></h3><p>Tieni premuto il <strong>pulsante sinistro arancione</strong> finché l&#39;orologio non vibra.</p><h3 id="relay-readings-to-your-phone-or-followers" tabindex="-1">Ritrasmettere le letture al telefono o ai follower <a class="header-anchor" href="#relay-readings-to-your-phone-or-followers" aria-label="Permalink to &quot;Ritrasmettere le letture al telefono o ai follower {#relay-readings-to-your-phone-or-followers}&quot;">​</a></h3><p>Quando l&#39;orologio è il collector, puoi comunque fornire i dati al telefono e ad altri dispositivi:</p><ul><li><strong>xDrip Link</strong>: orologio ↔ telefono tramite Bluetooth quando sono nel raggio d&#39;azione. Sull&#39;orologio apri l&#39;app <strong>xDrip Link</strong>, attivala e scansiona il suo codice QR in xDrip sul telefono, <strong>Impostazioni › Configurazione automatica</strong>. Le impostazioni BlueJay inserite sul telefono (compresi TXID e codice di accoppiamento) vengono copiate sull&#39;orologio. Se il telefono non deve collegarsi direttamente al sensore, imposta <a href="#run-phone-collector">Run Phone Collector</a> su <strong>Off</strong> sul telefono.</li><li><strong>xDrip Sync</strong>: ritrasmette le letture via internet (Wi-Fi/4G) da un master a uno o più follower, anche da orologio a orologio e da telefono a orologio.</li></ul><div class="info custom-block"><p class="custom-block-title">Funzioni dell&#39;orologio non legate a xDrip</p><p>L&#39;inserimento della SIM, il Wi-Fi, la fotocamera, i quadranti, i cinturini, le pellicole protettive, l&#39;account Google, le chiamate, il GPS, le chiamate SOS, la musica e l&#39;aggiornamento software dell&#39;orologio sono documentati dal produttore. Vedi le <a href="https://bluejay.website/faq" target="_blank" rel="noreferrer">Top Tips / FAQ</a> di BlueJay.</p></div><h2 id="legacy-models-x2-gts" tabindex="-1">Modelli precedenti: X2 / GTS <a class="header-anchor" href="#legacy-models-x2-gts" aria-label="Permalink to &quot;Modelli precedenti: X2 / GTS {#legacy-models-x2-gts}&quot;">​</a></h2><p>I passaggi seguenti riguardano i vecchi orologi X2 e GTS, che non sono più in vendita.</p><h3 id="pair-your-watch-to-xdrip-x2-and-gts" tabindex="-1">Associare l&#39;orologio a xDrip (X2 e GTS) <a class="header-anchor" href="#pair-your-watch-to-xdrip-x2-and-gts" aria-label="Permalink to &quot;Associare l&#39;orologio a xDrip (X2 e GTS) {#pair-your-watch-to-xdrip-x2-and-gts}&quot;">​</a></h3><p>1 - Assicurati che l&#39;orologio sia carico prima di iniziare.</p><p>2 - Attiva BlueJay e disattiva il collector dell&#39;orologio.</p><div class="admonition xdripitem"><p class="admonition-title">BlueJay Watch <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Run Collector <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p></div><p>3 - Se hai un BlueJay GTS, passa al punto 6.<br> Se hai un BlueJay X2, dovrebbe mostrare un codice QR sullo schermo.<br><img src="'+l+'" style="zoom:40%;"><br> Se lo vedi, passa al punto 7.</p><p>4 - Avvia BlueJay Panel e fai la scansione.</p><div class="admonition xdripitem"><p class="admonition-title">Launch BlueJay Panel</p></div><img src="'+r+'" style="zoom:76%;"> Quando l&#39;orologio viene rilevato dovresti vedere il suo indirizzo MAC. Selezionalo. <img src="'+n+'" style="zoom:66%;"><br> Se xDrip non trova l&#39;orologio, prova a riavviare il telefono e riprova. Se ancora non lo trovi, puoi inserire manualmente qui l&#39;indirizzo MAC dell&#39;orologio <div class="admonition xdripitem"><p class="admonition-title">BlueJay Advanced Settings</p><p> BlueJay Mac</p></div><p>Ora il codice QR dovrebbe comparire sull&#39;orologio; se lo vedi, passa al punto 7.</p><p>5 - Se il codice QR non è comparso sull&#39;orologio, seleziona QR e riprova.<br><img src="'+s+'" style="zoom:76%;"><br> Se ancora non vedi il codice QR, prova REBOOT, poi <a href="https://bluejay.website/contactus" target="_blank" rel="noreferrer">contatta</a> il produttore per assistenza o chiedi aiuto <a href="https://gitter.im/jamorham/BlueJay" target="_blank" rel="noreferrer">qui</a>.</p><p>6 - Sul GTS segui questa sequenza di menu per mostrare il codice QR:<br> Settings Menu -&gt; Admin Menu -&gt; Show QR Code<br><img src="'+p+'" style="zoom:76%;"></p><p>7 - In xDrip scansiona il codice QR dell&#39;orologio</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Configurazione automatica</p></div><p>Devi autorizzare xDrip ad accedere alla fotocamera del telefono.<br> Scansiona il codice QR mostrato sull&#39;orologio.<br><img src="'+c+'" style="zoom:50%;"></p><p>Configura l&#39;orologio come follower e dovresti vedere la tua glicemia entro pochi minuti.</p><div class="admonition xdripitem"><p class="admonition-title">BlueJay Watch <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Run Collector <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Invia Letture <span class="symbol"><img src="'+b+'" style="zoom:75%;"></span></p></div><p>Controlla lo <a href="./../troubleshoot/systemstatus.html">Stato del sistema</a> per verificare che l&#39;orologio sia associato correttamente. Scorri fino alla scheda di stato avanzato BlueJay.</p><img src="'+d+'" style="zoom:66%;"><p>Se il core di xDrip non è installato, installalo ora.</p><h3 id="install-the-xdrip-core" tabindex="-1">Installare il core di xDrip <a class="header-anchor" href="#install-the-xdrip-core" aria-label="Permalink to &quot;Installare il core di xDrip {#install-the-xdrip-core}&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Metti l&#39;orologio in carica durante l&#39;installazione del core</p></div><p>In Stato del sistema di xDrip, stato avanzato BlueJay, tocca la riga rossa xDrip Core: Not Installed.</p><img src="'+u+'" style="zoom:71%;"><p>Seleziona OK per aggiornare l&#39;orologio.</p><img src="'+m+'" style="zoom:79%;"><p>Controlla poi lo Stato del sistema: dovresti vedere il core installato.</p><img src="'+g+'" style="zoom:66%;"><h3 id="run-collector" tabindex="-1">Run collector <a class="header-anchor" href="#run-collector" aria-label="Permalink to &quot;Run collector {#run-collector}&quot;">​</a></h3><p>Run collector significa che userai l&#39;orologio senza dover necessariamente avere il telefono con te.</p><p>Se usi un modello X2, devi configurare l&#39;orologio con xDrip.<br> Per il GTS puoi farlo direttamente dal <a href="https://bluejay.website/gts-menu-top" target="_blank" rel="noreferrer">menu</a> dell&#39;orologio, senza usare xDrip.</p><p>Per usare l&#39;orologio con xDrip devi avere un trasmettitore collegato direttamente a xDrip, con i dati della glicemia attualmente visualizzati in xDrip.</p><p>Definisci quale slot si collegherà al trasmettitore. Consulta la tabella <a href="#g6g7-and-11">qui sopra</a> per configurare gli slot.</p><div class="admonition xdripitem"><p class="admonition-title">BlueJay Advanced Settings</p></div><h5 id="run-phone-collector" tabindex="-1">Run Phone Collector <a class="header-anchor" href="#run-phone-collector" aria-label="Permalink to &quot;Run Phone Collector {#run-phone-collector}&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">Run Phone Collector <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Also run the standard collector on this phone. Only turn this off if you don&#39;t want this phone itself to be connecting to the transmitter.</p></div><p>Attiva o disattiva la connessione di xDrip al trasmettitore (tramite lo slot phone).</p><h5 id="bluejay-uses-phone-slot" tabindex="-1">BlueJay uses Phone Slot <a class="header-anchor" href="#bluejay-uses-phone-slot" aria-label="Permalink to &quot;BlueJay uses Phone Slot {#bluejay-uses-phone-slot}&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">BlueJay uses Phone Slot <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> This allows the BlueJay to occupy the phone slot on the transmitter. Select this if you want another non-phone device to be able to connect to the transmitter and you are not using a phone to connect to the transmitter.</p></div><p>Per impostazione predefinita BlueJay usa lo slot non-phone. Con questa opzione puoi fargli usare lo slot phone, ma devi allora disattivare Run Phone Collector qui sopra.</p><p>Una volta configurati gli slot, puoi attivare l&#39;orologio come dispositivo collector autonomo.</p><div class="admonition xdripitem"><p class="admonition-title">BlueJay Watch <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Run Collector <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p></div><p>Vedrai allora che xDrip sul telefono non è più collegato al trasmettitore: lo è BlueJay.<br> Quando l&#39;orologio è nel raggio d&#39;azione Bluetooth, il telefono dovrebbe ricevere la glicemia da BlueJay.</p><img src="'+h+'" style="zoom:66%;"><h2 id="bluejay-gts" tabindex="-1">BlueJay GTS <a class="header-anchor" href="#bluejay-gts" aria-label="Permalink to &quot;BlueJay GTS {#bluejay-gts}&quot;">​</a></h2><p>Il GTS non ha bisogno di xDrip per essere configurato, ma se vuoi farlo i passaggi qui sopra valgono anche per lui.</p><p>Guarda il video <a href="https://www.youtube.com/watch?v=JM5cw-xVAZk" target="_blank" rel="noreferrer">qui</a> per una visita guidata.</p><p>Guarda qui <a href="https://www.youtube.com/watch?v=6YpjuZe2c_Q" target="_blank" rel="noreferrer">come</a> collegarti al trasmettitore.</p><h2 id="bluejay-u1u2-legacy" tabindex="-1">BlueJay U1/U2 (modelli precedenti) <a class="header-anchor" href="#bluejay-u1u2-legacy" aria-label="Permalink to &quot;BlueJay U1/U2 (modelli precedenti) {#bluejay-u1u2-legacy}&quot;">​</a></h2><p>Gli U1 e U2 non sono più in vendita ma eseguono lo stesso pacchetto xDrip completo dell&#39;U3, quindi vale la <a href="#bluejay-u3">configurazione dell&#39;U3</a> qui sopra. Consulta le <a href="https://bluejay.website/faq" target="_blank" rel="noreferrer">Top Tips / FAQ</a> del produttore per i consigli sugli orologi della serie U.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.11.26" target="_blank" rel="noreferrer"><em>Ultima modifica 18/7/2026</em></a></p>',93)])])}const R=f(z,[["render",_]]);export{j as __pageData,R as default};
